(function () {
  var KEY = '__ccbgTelecomUploadProbe';
  var MAX_EVENTS = 128;
  function getState() {
    var existing = window[KEY];
    if (existing && typeof existing === 'object') {
      if (!Array.isArray(existing.events)) {
        existing.events = [];
      }
      if (!Array.isArray(existing.surface_snapshots)) {
        existing.surface_snapshots = [];
      }
      if (!isFinite(Number(existing.event_seq || 0))) {
        existing.event_seq = 0;
      }
      return existing;
    }
    var created = {
      installed_at_unix_ms: Date.now(),
      event_seq: 0,
      events: [],
      surface_snapshots: [],
      installed: false,
      fetch_wrapped: false,
      xhr_wrapped: false
    };
    window[KEY] = created;
    return created;
  }
  var state = getState();
  function normalize(value) {
    return String(value || '').replace(/\s+/g, ' ').trim();
  }
  function safeStringify(value) {
    try {
      return JSON.stringify(value);
    } catch (error) {
      return String(value || '');
    }
  }
  function summarizeHeaders(headersLike) {
    try {
      if (!headersLike) {
        return { names: [], content_type: null };
      }
      var entries = [];
      if (typeof Headers !== 'undefined' && headersLike instanceof Headers) {
        headersLike.forEach(function (value, key) {
          entries.push([key, value]);
        });
      } else if (typeof headersLike === 'string') {
        headersLike.split(/\r?\n/).forEach(function (line) {
          var pivot = line.indexOf(':');
          if (pivot <= 0) {
            return;
          }
          entries.push([line.slice(0, pivot), line.slice(pivot + 1)]);
        });
      } else if (Array.isArray(headersLike)) {
        headersLike.forEach(function (entry) {
          if (Array.isArray(entry) && entry.length >= 2) {
            entries.push([entry[0], entry[1]]);
          }
        });
      } else if (typeof headersLike === 'object') {
        Object.keys(headersLike).forEach(function (key) {
          entries.push([key, headersLike[key]]);
        });
      }
      var names = entries
        .map(function (pair) { return String(pair[0] || '').toLowerCase(); })
        .filter(Boolean)
        .slice(0, 32);
      var contentTypeEntry = null;
      for (var i = 0; i < entries.length; i += 1) {
        if (String(entries[i][0] || '').toLowerCase() === 'content-type') {
          contentTypeEntry = entries[i];
          break;
        }
      }
      return {
        names: names,
        content_type: contentTypeEntry ? (String(contentTypeEntry[1] || '').trim() || null) : null
      };
    } catch (error) {
      return { names: [], content_type: null };
    }
  }
  function tryParseJson(value) {
    if (typeof value !== 'string') {
      return null;
    }
    try {
      return JSON.parse(value);
    } catch (error) {
      return null;
    }
  }
  function summarizeBody(body) {
    if (body === null || body === undefined) {
      return { kind: 'empty' };
    }
    if (typeof FormData !== 'undefined' && body instanceof FormData) {
      var fieldNames = [];
      var fileFields = [];
      var fileCount = 0;
      body.forEach(function (value, key) {
        fieldNames.push(String(key));
        if (typeof File !== 'undefined' && value instanceof File) {
          fileCount += 1;
          fileFields.push({ field: String(key), size_bytes: Number(value.size || 0), mime_type: String(value.type || '') || null });
        } else if (typeof Blob !== 'undefined' && value instanceof Blob) {
          fileCount += 1;
          fileFields.push({ field: String(key), size_bytes: Number(value.size || 0), mime_type: String(value.type || '') || null });
        }
      });
      return {
        kind: 'form_data',
        field_names: fieldNames.slice(0, 24),
        file_count: fileCount,
        file_fields: fileFields.slice(0, 12)
      };
    }
    if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) {
      return { kind: 'url_search_params', field_names: Array.from(body.keys()).slice(0, 24) };
    }
    if (typeof File !== 'undefined' && body instanceof File) {
      return { kind: 'file', size_bytes: Number(body.size || 0), mime_type: String(body.type || '') || null };
    }
    if (typeof Blob !== 'undefined' && body instanceof Blob) {
      return { kind: 'blob', size_bytes: Number(body.size || 0), mime_type: String(body.type || '') || null };
    }
    if (typeof ArrayBuffer !== 'undefined' && body instanceof ArrayBuffer) {
      return { kind: 'array_buffer', size_bytes: Number(body.byteLength || 0) };
    }
    if (typeof body === 'string') {
      var parsed = tryParseJson(body);
      var jsonKeys = parsed && typeof parsed === 'object' && !Array.isArray(parsed)
        ? Object.keys(parsed).slice(0, 24)
        : [];
      return {
        kind: 'string',
        length: body.length,
        preview: body.slice(0, 320),
        json_keys: jsonKeys,
        parsed_json: parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null
      };
    }
    if (typeof body === 'object') {
      return { kind: 'object', keys: Object.keys(body).slice(0, 24), parsed_json: body };
    }
    return { kind: typeof body };
  }
  function isTextualContentType(contentType) {
    var value = String(contentType || '').toLowerCase();
    if (!value) {
      return true;
    }
    return value.indexOf('json') >= 0 ||
      value.indexOf('text/') >= 0 ||
      value.indexOf('javascript') >= 0 ||
      value.indexOf('xml') >= 0 ||
      value.indexOf('html') >= 0 ||
      value.indexOf('x-www-form-urlencoded') >= 0;
  }
  function isUploadCandidate(url, method, headerSummary, bodySummary) {
    var urlText = String(url || '');
    var methodText = String(method || '').toUpperCase();
    var names = Array.isArray(headerSummary && headerSummary.names) ? headerSummary.names.join(' ') : '';
    var contentType = String((headerSummary && headerSummary.content_type) || '');
    if (/(upload|getMultiUploadUrls|checkTransSecond|commitMultiUploadFile|put|multipart|create|save|commit|chunk|part|file|folder)/i.test(urlText) && !/listFiles\.action/i.test(urlText)) {
      return true;
    }
    if (methodText === 'PUT') {
      return true;
    }
    if (/(multipart\/form-data|octet-stream|content-range)/i.test(contentType + ' ' + names)) {
      return true;
    }
    return Number((bodySummary && bodySummary.file_count) || 0) > 0 ||
      (bodySummary && bodySummary.kind) === 'file' ||
      (bodySummary && bodySummary.kind) === 'blob';
  }
  function updateEvent(eventId, patch) {
    if (!eventId || !patch || typeof patch !== 'object') {
      return;
    }
    var current = getState();
    var events = Array.isArray(current.events) ? current.events : [];
    for (var i = events.length - 1; i >= 0; i -= 1) {
      if (events[i] && events[i].id === eventId) {
        var merged = {};
        Object.keys(events[i]).forEach(function (key) { merged[key] = events[i][key]; });
        Object.keys(patch).forEach(function (key) { merged[key] = patch[key]; });
        events[i] = merged;
        current.events = events;
        return;
      }
    }
  }
  function recordEvent(transport, method, url, headersLike, body) {
    try {
      var headerSummary = summarizeHeaders(headersLike);
      var bodySummary = summarizeBody(body);
      var current = getState();
      current.event_seq = Number(current.event_seq || 0) + 1;
      var entry = {
        id: 'evt-' + Date.now() + '-' + String(current.event_seq),
        transport: transport,
        method: String(method || '').toUpperCase() || null,
        url: String(url || '') || null,
        captured_at_unix_ms: Date.now(),
        header_names: headerSummary.names || [],
        content_type: headerSummary.content_type || null,
        body: bodySummary,
        is_upload_candidate: isUploadCandidate(url, method, headerSummary, bodySummary)
      };
      current.events = Array.isArray(current.events) ? current.events : [];
      current.events.push(entry);
      if (current.events.length > MAX_EVENTS) {
        current.events = current.events.slice(-MAX_EVENTS);
      }
      return { id: entry.id, is_upload_candidate: entry.is_upload_candidate };
    } catch (error) {
      return null;
    }
  }
  function attachResponse(eventMeta, patch) {
    if (!eventMeta || !eventMeta.id || !patch || typeof patch !== 'object') {
      return;
    }
    updateEvent(eventMeta.id, patch);
  }
  if (!state.fetch_wrapped && typeof window.fetch === 'function') {
    var originalFetch = window.fetch.bind(window);
    window.fetch = function (input, init) {
      var request = typeof Request !== 'undefined' && input instanceof Request ? input : null;
      var method = (init && init.method) || (request && request.method) || 'GET';
      var url = typeof input === 'string' ? input : ((request && request.url) || '');
      var headers = (init && init.headers) || (request && request.headers) || null;
      var body = init && Object.prototype.hasOwnProperty.call(init, 'body') ? init.body : (request && request._bodyInit) || null;
      var eventMeta = recordEvent('fetch', method, url, headers, body);
      var startedAtUnixMs = Date.now();
      return originalFetch(input, init).then(function (response) {
        var responseHeaderSummary = summarizeHeaders(response && response.headers ? response.headers : null);
        var patch = {
          response_status: Number((response && response.status) || 0),
          response_ok: !!(response && response.ok),
          response_url: String((response && response.url) || url || '') || null,
          response_content_type: responseHeaderSummary.content_type || null,
          response_header_names: responseHeaderSummary.names || [],
          completed_at_unix_ms: Date.now(),
          elapsed_ms: Math.max(0, Date.now() - startedAtUnixMs)
        };
        if (!(eventMeta && eventMeta.is_upload_candidate)) {
          attachResponse(eventMeta, patch);
          return response;
        }
        if (response && response.type === 'opaque') {
          patch.response_body = { kind: 'omitted', reason: 'opaque' };
          attachResponse(eventMeta, patch);
          return response;
        }
        if (!isTextualContentType(patch.response_content_type)) {
          patch.response_body = { kind: 'omitted', reason: 'non_textual' };
          attachResponse(eventMeta, patch);
          return response;
        }
        response.clone().text().then(function (text) {
          patch.response_body = summarizeBody(text);
          attachResponse(eventMeta, patch);
        }).catch(function (error) {
          patch.response_body = {
            kind: 'unavailable',
            message: normalize((error && error.message) || String(error || 'response read failed')) || 'response read failed'
          };
          attachResponse(eventMeta, patch);
        });
        return response;
      }).catch(function (error) {
        attachResponse(eventMeta, {
          network_error: normalize((error && error.message) || String(error || 'fetch failed')) || 'fetch failed',
          completed_at_unix_ms: Date.now(),
          elapsed_ms: Math.max(0, Date.now() - startedAtUnixMs)
        });
        throw error;
      });
    };
    state.fetch_wrapped = true;
  }
  if (!state.xhr_wrapped && typeof XMLHttpRequest !== 'undefined') {
    var proto = XMLHttpRequest.prototype;
    if (!proto.__ccbgTelecomUploadProbeWrapped) {
      var originalOpen = proto.open;
      var originalSend = proto.send;
      var originalSetRequestHeader = proto.setRequestHeader;
      proto.open = function (method, url) {
        this.__ccbgProbeMethod = method;
        this.__ccbgProbeUrl = url;
        this.__ccbgProbeHeaders = [];
        return originalOpen.apply(this, arguments);
      };
      proto.setRequestHeader = function (name, value) {
        try {
          var list = Array.isArray(this.__ccbgProbeHeaders) ? this.__ccbgProbeHeaders : [];
          list.push([name, value]);
          this.__ccbgProbeHeaders = list;
        } catch (error) {}
        return originalSetRequestHeader.apply(this, arguments);
      };
      proto.send = function (body) {
        var self = this;
        var eventMeta = recordEvent('xhr', this.__ccbgProbeMethod || 'GET', this.__ccbgProbeUrl || '', this.__ccbgProbeHeaders || [], body);
        var startedAtUnixMs = Date.now();
        this.addEventListener('loadend', function () {
          var responseHeaderSummary = summarizeHeaders(typeof self.getAllResponseHeaders === 'function' ? self.getAllResponseHeaders() : null);
          var patch = {
            response_status: Number(self.status || 0),
            response_ok: Number(self.status || 0) >= 200 && Number(self.status || 0) < 300,
            response_url: String(self.responseURL || self.__ccbgProbeUrl || '') || null,
            response_content_type: responseHeaderSummary.content_type || null,
            response_header_names: responseHeaderSummary.names || [],
            completed_at_unix_ms: Date.now(),
            elapsed_ms: Math.max(0, Date.now() - startedAtUnixMs)
          };
          if (!(eventMeta && eventMeta.is_upload_candidate)) {
            attachResponse(eventMeta, patch);
            return;
          }
          var responseType = String(self.responseType || '').toLowerCase();
          if (responseType && responseType !== 'text' && responseType !== 'json') {
            patch.response_body = { kind: 'omitted', reason: 'xhr_response_type:' + responseType };
            attachResponse(eventMeta, patch);
            return;
          }
          if (!isTextualContentType(patch.response_content_type)) {
            patch.response_body = { kind: 'omitted', reason: 'non_textual' };
            attachResponse(eventMeta, patch);
            return;
          }
          try {
            var responseValue = responseType === 'json' ? safeStringify(self.response) : String(self.responseText || '');
            patch.response_body = summarizeBody(responseValue);
          } catch (error) {
            patch.response_body = {
              kind: 'unavailable',
              message: normalize((error && error.message) || String(error || 'xhr response read failed')) || 'xhr response read failed'
            };
          }
          attachResponse(eventMeta, patch);
        }, { once: true });
        return originalSend.apply(this, arguments);
      };
      proto.__ccbgTelecomUploadProbeWrapped = true;
    }
    state.xhr_wrapped = true;
  }
  state.installed = true;
  return {
    installed: true,
    fetch_wrapped: !!state.fetch_wrapped,
    xhr_wrapped: !!state.xhr_wrapped,
    event_count: Array.isArray(state.events) ? state.events.length : 0
  };
})()
